style.css:
@-moz-document domain("docs.google.com") {
/* =================================================
   VARIABLES
================================================= */

:root {
  bg-paper: rgba(9, 9, 9, 0.94); 
  blood-red: #8a0f1a; 
  blood-glow: #b01c2f; 
  text-main: #e9e6e6; 
  border-soft: rgba(255,255,255,0.08); 

  bg-image: url("https://drive.google.com/uc?export=view&id=10UY3ebxR9yi1tYPQXnUNPkArd2WQcHNJ"); 
}

/* =================================================
   FONDO GENERAL — APLICADO A TODO
================================================= */

html,
body,
.docs-texteventtarget-iframe,
.kix-appview-editor,
.docs-texteventtarget-iframe iframe {
  background:
    linear-gradient(rgba(0,0,0,.82), rgba(0,0,0,.82)),
    var(--bg-image) !important;

  background-size: cover !important;
  background-position: center !important;
  background-attachment: fixed !important;
}

/* =================================================
   PÁGINAS
================================================= */

.kix-page {
  background: var(--bg-paper) !important;
  border-radius: 18px !important;
  border: 1px solid var(--border-soft) !important;
  box-shadow:
    0 0 40px rgba(138,15,26,.45),
    0 0 120px rgba(0,0,0,.95) !important;
}

/* =================================================
   TEXTO GENERAL
================================================= */

.kix-lineview-content,
.kix-paragraphrenderer,
.kix-wordhtmlgenerator-word-node {
  color: var(--text-main) !important;
}

/* =================================================
   TÍTULOS — BRILLO LUNAR (SEGURO)
================================================= */

.kix-paragraphrenderer[aria-label*="Heading"],
.kix-paragraphrenderer[aria-label*="Título"] {
  text-shadow:
    0 0 6px rgba(255,255,255,.35),
    0 0 14px rgba(176,28,47,.25),
    0 0 30px rgba(0,0,0,.9) !important;
}

/* =================================================
   SELECCIÓN
================================================= */

::selection {
  background: rgba(138,15,26,.85) !important;
  color: #fff !important;
  text-shadow:
    0 0 6px rgba(176,28,47,.8),
    0 0 14px rgba(138,15,26,.6) !important;
}

/* =================================================
   CURSOR
================================================= */

.kix-cursor-caret {
  border-left: 2px solid var(--blood-glow) !important;
}

/* =================================================
   BARRAS SUPERIORES
================================================= */

.docs-titlebar,
.docs-menubar,
.docs-toolbar-wrapper {
  background: rgba(8,8,8,.96) !important;
  border-bottom: 1px solid var(--border-soft) !important;
}

/* =================================================
   BOTONES
================================================= */

.docs-toolbar-button:hover,
.goog-toolbar-button:hover {
  background: rgba(138,15,26,.35) !important;
}

/* =================================================
   COMENTARIOS
================================================= */

.docs-comment-box {
  background: #111 !important;
  border: 1px solid var(--blood-red) !important;
  color: var(--text-main) !important;
}

/* =================================================
   SCROLL
================================================= */

::-webkit-scrollbar {
  width: 10px;
}

::-webkit-scrollbar-track {
  background: #0a0a0a;
}

::-webkit-scrollbar-thumb {
  background: var(--blood-red);
  border-radius: 10px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--blood-glow);
}
}
